// ---------------------------------------------------------------------------
// 3. DIAMOND ALGORITHM (Deluxe Album Cover Geometry)
// ---------------------------------------------------------------------------
export function hasDecimal(number) {
  const sqrt = Math.sqrt(number);
  return sqrt !== Math.floor(sqrt);
}

export function createDiamond(sentence) {
  if (!sentence || typeof sentence !== 'string') return [];
  const words = sentence.trim().split(/\s+/);
  const len = words.length;
  if (len === 0) return [];
  if (len === 1) return [words[0]];

  const groups = [];
  let num1 = 0;
  let num2 = 0;
  const sqrtlen = Math.floor(Math.sqrt(len));

  for (let i = 0; i < sqrtlen; i++) {
    num1 = num2;
    num2 = num2 + i + 1;
    groups.push(words.slice(num1, num2));
  }

  if (hasDecimal(len)) {
    for (let j = sqrtlen; j >= 1; j--) {
      num1 = num2;
      num2 = num2 + j;
      groups.push(words.slice(num1, num2));
    }
    if (len > num2) {
      for (let z = 0; z < len - num2; z++) {
        num1 = num2;
        num2 = num2 + 1;
        groups.push(words.slice(num1, num2));
      }
    }
  } else {
    for (let j = sqrtlen; j > 1; j--) {
      num1 = num2;
      num2 = num2 + j - 1;
      groups.push(words.slice(num1, num2));
    }
  }

  const resultRows = [];
  groups.forEach(function (group) {
    if (group && group.length > 0) {
      resultRows.push(group.join(' '));
    }
  });

  return resultRows;
}

// ---------------------------------------------------------------------------
// 4. TEXT FITTING & METRICS CALCULATION
// ---------------------------------------------------------------------------
export function calculateTextFit(text, options = {}) {
  const containerWidth = options.containerWidth || 500;
  const containerHeight = options.containerHeight || 500;
  const maxFontSize = options.maxFontSize || 80;
  const minFontSize = options.minFontSize || 10;
  const isDiamond = options.diamond || false;

  let lines = [];
  if (Array.isArray(text)) {
    lines = text;
  } else if (isDiamond) {
    lines = createDiamond(text);
  } else {
    lines = String(text).split('\n');
  }

  let maxLineLength = Math.max(...lines.map(l => l.length), 1);
  let lineCount = Math.max(lines.length, 1);

  if (!isDiamond && !Array.isArray(text) && lines.length === 1 && text.length > 15) {
    const words = text.split(/\s+/);
    const targetLines = Math.min(Math.ceil(words.length / 3), 6);
    const wordsPerLine = Math.ceil(words.length / targetLines);
    const wrapped = [];
    for (let i = 0; i < words.length; i += wordsPerLine) {
      wrapped.push(words.slice(i, i + wordsPerLine).join(' '));
    }
    lines = wrapped;
    maxLineLength = Math.max(...lines.map(l => l.length), 1);
    lineCount = lines.length;
  }

  let estFontSizeW = (containerWidth * 0.85) / (maxLineLength * 0.52);
  let estFontSizeH = (containerHeight * 0.85) / (lineCount * 1.25);
  let fontSize = Math.min(estFontSizeW, estFontSizeH, maxFontSize);
  fontSize = Math.max(fontSize, minFontSize);

  const lineHeight = fontSize * 1.15;
  return {
    lines,
    fontSize: Math.round(fontSize * 10) / 10,
    lineHeight: Math.round(lineHeight * 10) / 10
  };
}

// ---------------------------------------------------------------------------
// 5. SVG RENDERING ENGINE
// ---------------------------------------------------------------------------
export function generateBratSVG(params = {}) {
  const themeKey = (params.theme || 'green').toLowerCase();
  const theme = THEMES[themeKey] || THEMES.green;
  const width = params.width || 800;
  const height = params.height || 800;
  const text = (params.text !== undefined && params.text !== null && params.text !== '') ? params.text : theme.defaultText;
  const blur = params.blur !== undefined ? Number(params.blur) : theme.blur;
  const isDiamond = params.diamond !== undefined ? Boolean(params.diamond) : theme.diamond;
  const isStrike = params.strike !== undefined ? Boolean(params.strike) : theme.strike;

  const fitResult = calculateTextFit(text, {
    containerWidth: width * 0.82,
    containerHeight: height * 0.82,
    maxFontSize: theme.maxFontSize * (width / 500),
    minFontSize: 12,
    diamond: isDiamond
  });

  const lines = fitResult.lines;
  const fontSize = fitResult.fontSize;
  const lineHeight = fitResult.lineHeight;
  const totalTextHeight = lines.length * lineHeight;
  const startY = (height / 2) - (totalTextHeight / 2) + (fontSize * 0.78);

  let bgImageTag = '';
  if (params.embedBackground !== false && theme.bgDataUri) {
    bgImageTag = '<image href="' + theme.bgDataUri + '" x="0" y="0" width="' + width + '" height="' + height + '" preserveAspectRatio="xMidYMid slice" />';
  }

  let strikeOverlay = '';
  if (isStrike) {
    if (theme.strikeDataUri) {
      strikeOverlay = '<image href="' + theme.strikeDataUri + '" x="' + (width * 0.1) + '" y="' + (height * 0.4) + '" width="' + (width * 0.8) + '" height="' + (height * 0.2) + '" preserveAspectRatio="xMidYMid meet" filter="url(#bratBlur)" />';
    } else {
      strikeOverlay = '<line x1="' + (width * 0.2) + '" y1="' + (height * 0.5) + '" x2="' + (width * 0.8) + '" y2="' + (height * 0.5) + '" stroke="#D41C2B" stroke-width="' + (fontSize * 0.18) + '" stroke-linecap="round" filter="url(#bratBlur)" />';
    }
  }

  const svgLines = lines.map(function(line, idx) {
    const yPos = startY + (idx * lineHeight);
    const safeLine = line.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    return '<text x="' + (width / 2) + '" y="' + Math.round(yPos) + '" font-size="' + fontSize + 'px" class="brat-text">' + safeLine + '</text>';
  }).join('\n    ');

  return '<?xml version="1.0" encoding="UTF-8"?>\n' +
'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + width + ' ' + height + '" width="' + width + '" height="' + height + '">\n' +
'  <defs>\n' +
'    <filter id="bratBlur" x="-20%" y="-20%" width="140%" height="140%">\n' +
'      <feGaussianBlur stdDeviation="' + blur + '" />\n' +
'    </filter>\n' +
'    <style>\n' +
'      @import url(\'https://fonts.googleapis.com/css2?family=Archivo+Narrow:ital,wght@0,400..700;1,400..700&amp;display=swap\');\n' +
'      .brat-text {\n' +
'        font-family: ' + theme.fontFamily + ';\n' +
'        font-weight: 400;\n' +
'        font-stretch: condensed;\n' +
'        fill: ' + theme.textColor + ';\n' +
'        text-anchor: middle;\n' +
'        dominant-baseline: central;\n' +
'        letter-spacing: -0.04em;\n' +
'        filter: url(#bratBlur);\n' +
'      }\n' +
'    </style>\n' +
'  </defs>\n' +
'  <!-- Background -->\n' +
'  <rect width="' + width + '" height="' + height + '" fill="' + theme.bgColor + '" />\n' +
'  ' + bgImageTag + '\n' +
'  <!-- Text Layer -->\n' +
'  <g class="brat-text-group">\n' +
'    ' + svgLines + '\n' +
'  </g>\n' +
'  ' + strikeOverlay + '\n' +
'</svg>';
}

export const generateSVG = generateBratSVG;


