export function getEmbeddedHtml() {
  return "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Brat Generator - Standalone Edition</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Archivo+Narrow:ital,wght@0,400..700;1,400..700&family=Inter:wght@400;600;800&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root {\n      --lime: #8ACE00;\n      --bg: #121212;\n      --card-bg: #1e1e1e;\n      --text: #f0f0f0;\n      --muted: #888888;\n    }\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body {\n      font-family: 'Inter', sans-serif;\n      background-color: var(--bg);\n      color: var(--text);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      padding: 24px 16px;\n    }\n    header {\n      text-align: center;\n      margin-bottom: 24px;\n    }\n    h1 {\n      font-family: 'Archivo Narrow', sans-serif;\n      font-size: 2.8rem;\n      font-weight: 700;\n      letter-spacing: -0.05em;\n      color: var(--lime);\n      text-transform: lowercase;\n      filter: blur(0.4px);\n    }\n    .subtitle {\n      color: var(--muted);\n      font-size: 0.95rem;\n      margin-top: 4px;\n    }\n    .container {\n      display: flex;\n      flex-direction: column;\n      gap: 28px;\n      max-width: 1050px;\n      width: 100%;\n    }\n    @media (min-width: 840px) {\n      .container {\n        flex-direction: row;\n        align-items: flex-start;\n      }\n    }\n    .preview-section {\n      flex: 1;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      background: var(--card-bg);\n      padding: 20px;\n      border-radius: 16px;\n      box-shadow: 0 10px 30px rgba(0,0,0,0.5);\n    }\n    .preview-box {\n      width: 100%;\n      max-width: 450px;\n      aspect-ratio: 1/1;\n      border-radius: 8px;\n      overflow: hidden;\n      box-shadow: 0 6px 20px rgba(0,0,0,0.4);\n      background: #8ACE00;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n    }\n    .preview-box svg {\n      width: 100%;\n      height: 100%;\n      display: block;\n    }\n    .controls-section {\n      flex: 1;\n      background: var(--card-bg);\n      padding: 24px;\n      border-radius: 16px;\n      display: flex;\n      flex-direction: column;\n      gap: 20px;\n      box-shadow: 0 10px 30px rgba(0,0,0,0.5);\n    }\n    .section-title {\n      font-size: 0.85rem;\n      text-transform: uppercase;\n      letter-spacing: 0.08em;\n      color: var(--muted);\n      font-weight: 600;\n    }\n    .theme-grid {\n      display: grid;\n      grid-template-columns: repeat(3, 1fr);\n      gap: 10px;\n    }\n    .theme-btn {\n      padding: 12px 8px;\n      border-radius: 8px;\n      border: 2px solid transparent;\n      cursor: pointer;\n      font-weight: 600;\n      font-size: 0.85rem;\n      text-align: center;\n      transition: all 0.2s;\n    }\n    .theme-btn:hover { transform: translateY(-2px); }\n    .theme-btn.active { border-color: #ffffff; box-shadow: 0 0 12px rgba(255,255,255,0.4); }\n    .theme-green { background: #8ACE00; color: #000; }\n    .theme-black { background: #1a1a1a; color: #fff; border: 1px solid #444; }\n    .theme-white { background: #ffffff; color: #000; }\n    .theme-strike { background: #8ACE00; color: #000; text-decoration: line-through; text-decoration-color: #d41c2b; }\n    .theme-red { background: #D41C2B; color: #fff; }\n    .theme-blue { background: #0A00AD; color: #F9FF3E; }\n    .input-group {\n      display: flex;\n      flex-direction: column;\n      gap: 8px;\n    }\n    textarea {\n      width: 100%;\n      height: 90px;\n      background: #121212;\n      border: 1px solid #333;\n      border-radius: 8px;\n      color: #fff;\n      font-family: inherit;\n      font-size: 1rem;\n      padding: 12px;\n      resize: vertical;\n    }\n    textarea:focus {\n      outline: none;\n      border-color: var(--lime);\n    }\n    .slider-group {\n      display: flex;\n      flex-direction: column;\n      gap: 6px;\n    }\n    .slider-row {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      color: var(--muted);\n      font-size: 0.85rem;\n    }\n    input[type=\"range\"] {\n      width: 100%;\n      accent-color: var(--lime);\n    }\n    .actions {\n      display: flex;\n      gap: 12px;\n    }\n    .btn {\n      flex: 1;\n      padding: 14px;\n      border-radius: 8px;\n      border: none;\n      cursor: pointer;\n      font-weight: 700;\n      font-size: 0.95rem;\n      transition: 0.2s;\n    }\n    .btn-primary {\n      background: var(--lime);\n      color: #000;\n    }\n    .btn-primary:hover {\n      background: #9cf000;\n    }\n    .btn-secondary {\n      background: #333;\n      color: #fff;\n    }\n    .btn-secondary:hover {\n      background: #444;\n    }\n    .api-info {\n      margin-top: 10px;\n      background: #121212;\n      padding: 12px;\n      border-radius: 8px;\n      font-family: monospace;\n      font-size: 0.8rem;\n      color: #aaa;\n    }\n  </style>\n</head>\n<body>\n  <header>\n    <h1>brat generator</h1>\n    <div class=\"subtitle\">100% Independent Standalone Single-File Node.js Suite</div>\n  </header>\n\n  <div class=\"container\">\n    <div class=\"preview-section\">\n      <div class=\"preview-box\" id=\"previewBox\"></div>\n    </div>\n\n    <div class=\"controls-section\">\n      <div>\n        <div class=\"section-title\" style=\"margin-bottom: 8px;\">Select Theme</div>\n        <div class=\"theme-grid\">\n          <button class=\"theme-btn theme-green active\" onclick=\"setTheme('green')\">Lime</button>\n          <button class=\"theme-btn theme-black\" onclick=\"setTheme('black')\">Deluxe</button>\n          <button class=\"theme-btn theme-white\" onclick=\"setTheme('white')\">White</button>\n          <button class=\"theme-btn theme-strike\" onclick=\"setTheme('strike')\">Strike</button>\n          <button class=\"theme-btn theme-red\" onclick=\"setTheme('red')\">Moment</button>\n          <button class=\"theme-btn theme-blue\" onclick=\"setTheme('blue')\">Sweat</button>\n        </div>\n      </div>\n\n      <div class=\"input-group\">\n        <div class=\"section-title\">Cover Text</div>\n        <textarea id=\"textInput\" placeholder=\"Type text here...\" oninput=\"update()\"></textarea>\n      </div>\n\n      <div class=\"slider-group\">\n        <div class=\"slider-row\">\n          <span>Blur Intensity</span>\n          <span id=\"blurVal\">1.5px</span>\n        </div>\n        <input type=\"range\" id=\"blurInput\" min=\"0\" max=\"4\" step=\"0.1\" value=\"1.5\" oninput=\"updateBlur(this.value)\">\n      </div>\n\n      <div class=\"actions\">\n        <button class=\"btn btn-primary\" onclick=\"downloadSVG()\">Download SVG</button>\n        <button class=\"btn btn-secondary\" onclick=\"downloadPNG()\">Download PNG</button>\n      </div>\n\n      <div class=\"api-info\">\n        <strong>REST API Endpoint:</strong><br>\n        <code>GET /api/generate?text=brat&theme=green&width=800</code>\n      </div>\n    </div>\n  </div>\n\n  <script>\n    let currentTheme = 'green';\n    let currentBlur = 1.5;\n\n    const DEFAULT_TEXTS = {\n      green: 'brat',\n      black: \"brat and it’s completely different but also still brat\",\n      white: \"brat and it’s completely different but also still brat\",\n      strike: 'brat',\n      red: 'the moment',\n      blue: 'SWEAT'\n    };\n\n    function setTheme(theme) {\n      currentTheme = theme;\n      document.querySelectorAll('.theme-btn').forEach(btn => btn.classList.remove('active'));\n      document.querySelector('.theme-' + theme).classList.add('active');\n      const input = document.getElementById('textInput');\n      input.value = DEFAULT_TEXTS[theme] || 'brat';\n      update();\n    }\n\n    function updateBlur(val) {\n      currentBlur = parseFloat(val);\n      document.getElementById('blurVal').innerText = currentBlur + 'px';\n      update();\n    }\n\n    async function update() {\n      const text = document.getElementById('textInput').value;\n      const url = '/api/generate?theme=' + encodeURIComponent(currentTheme) + '&text=' + encodeURIComponent(text) + '&blur=' + currentBlur + '&width=800&height=800';\n      const res = await fetch(url);\n      const svg = await res.text();\n      document.getElementById('previewBox').innerHTML = svg;\n    }\n\n    function downloadSVG() {\n      const svg = document.querySelector('#previewBox svg').outerHTML;\n      const blob = new Blob([svg], { type: 'image/svg+xml;charset=utf-8' });\n      const link = document.createElement('a');\n      link.href = URL.createObjectURL(blob);\n      link.download = 'brat_' + currentTheme + '_' + Date.now() + '.svg';\n      link.click();\n    }\n\n    function downloadPNG() {\n      const svgElement = document.querySelector('#previewBox svg');\n      const svgString = new XMLSerializer().serializeToString(svgElement);\n      const svgBlob = new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' });\n      const URLObj = window.URL || window.webkitURL || window;\n      const blobURL = URLObj.createObjectURL(svgBlob);\n      const image = new Image();\n      image.onload = function() {\n        const canvas = document.createElement('canvas');\n        canvas.width = 1600;\n        canvas.height = 1600;\n        const context = canvas.getContext('2d');\n        context.drawImage(image, 0, 0, 1600, 1600);\n        const png = canvas.toDataURL('image/png');\n        const link = document.createElement('a');\n        link.download = 'brat_' + currentTheme + '_' + Date.now() + '.png';\n        link.href = png;\n        link.click();\n      };\n      image.src = blobURL;\n    }\n\n    // Init\n    document.getElementById('textInput').value = DEFAULT_TEXTS.green;\n    update();\n  </script>\n</body>\n</html>";
}

// ---------------------------------------------------------------------------
// 7. EMBEDDED HTTP & REST API SERVER
// ---------------------------------------------------------------------------
export function startServer(port = 3000) {
  const server = http.createServer((req, res) => {
    const parsedUrl = url.parse(req.url, true);
    const pathname = parsedUrl.pathname;
    const query = parsedUrl.query;

    // Enable CORS
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

    if (req.method === 'OPTIONS') {
      res.writeHead(200);
      return res.end();
    }

    // 1. Root: Serve Embedded Web Interface
    if (pathname === '/' || pathname === '/index.html') {
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      return res.end(getEmbeddedHtml());
    }

    // 2. REST API: /api/generate (SVG Output)
    if (pathname === '/api/generate' || pathname === '/svg') {
      const theme = query.theme || 'green';
      const text = query.text !== undefined ? query.text : undefined;
      const width = query.width ? parseInt(query.width, 10) : 800;
      const height = query.height ? parseInt(query.height, 10) : 800;
      const blur = query.blur !== undefined ? parseFloat(query.blur) : undefined;
      const diamond = query.diamond !== undefined ? (query.diamond === 'true' || query.diamond === '1') : undefined;
      const strike = query.strike !== undefined ? (query.strike === 'true' || query.strike === '1') : undefined;

      const svg = generateBratSVG({ theme, text, width, height, blur, diamond, strike });
      res.writeHead(200, { 'Content-Type': 'image/svg+xml; charset=utf-8' });
      return res.end(svg);
    }

    // 3. REST API: /api/themes (JSON Theme list)
    if (pathname === '/api/themes') {
      const themeList = Object.keys(THEMES).map(k => ({
        id: THEMES[k].id,
        name: THEMES[k].name,
        bgColor: THEMES[k].bgColor,
        textColor: THEMES[k].textColor,
        defaultText: THEMES[k].defaultText,
        diamond: THEMES[k].diamond,
        strike: THEMES[k].strike
      }));
      res.writeHead(200, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify(themeList, null, 2));
    }

    // 4. REST API: /api/diamond (Word geometry breakdown)
    if (pathname === '/api/diamond') {
      const sentence = query.text || "brat and it's completely different but also still brat";
      const rows = createDiamond(sentence);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ sentence, rows, count: rows.length }, null, 2));
    }

    // 404
    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('404 Not Found');
  });

  server.listen(port, () => {
    console.log('===========================================================');
    console.log('💚 BRAT GENERATOR (100% Independent Standalone Node.js)');
    console.log('===========================================================');
    console.log('🌐 Web Interface: http://localhost:' + port);
    console.log('🎨 REST API:      http://localhost:' + port + '/api/generate?text=brat&theme=green');
    console.log('📋 Theme List:    http://localhost:' + port + '/api/themes');
    console.log('===========================================================');
  });

  return server;
}

// ---------------------------------------------------------------------------
// 8. CLI & ENTRY POINT
// ---------------------------------------------------------------------------
function runCLI() {
  const args = process.argv.slice(2);
  let text = null;
  let theme = 'green';
  let outPath = null;
  let width = 800;
  let height = 800;
  let blur = null;
  let serve = false;
  let port = 3000;

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--serve' || arg === '-s') {
      serve = true;
      if (args[i + 1] && !args[i + 1].startsWith('-')) {
        port = parseInt(args[++i], 10) || 3000;
      }
    } else if (arg === '--text' || arg === '-t') {
      text = args[++i];
    } else if (arg === '--theme') {
      theme = args[++i];
    } else if (arg === '--out' || arg === '-o') {
      outPath = args[++i];
    } else if (arg === '--width' || arg === '-w') {
      width = parseInt(args[++i], 10) || 800;
    } else if (arg === '--height' || arg === '-h') {
      height = parseInt(args[++i], 10) || 800;
    } else if (arg === '--blur') {
      blur = parseFloat(args[++i]);
    }
  }

  if (outPath) {
    const svg = generateBratSVG({ text, theme, width, height, blur });
    fs.writeFileSync(outPath, svg, 'utf-8');
    console.log('✅ Generated Brat SVG saved to: ' + outPath);
    process.exit(0);
  }

  // Default behavior when invoked directly
  startServer(port);
}

const isMain = process.argv[1] && (path.resolve(process.argv[1]) === path.resolve(url.fileURLToPath(import.meta.url)));
if (isMain) {
  runCLI();
}

export default {
  THEMES,
  createDiamond,
  calculateTextFit,
  generateBratSVG,
  generateSVG: generateBratSVG,
  startServer,
  getEmbeddedHtml
};
